require 'app/bootstrap.php'; require_roles('Admin','Lễ tân');
$invoices=rows('SELECT t.*,k.HOTENKH FROM thuoc_hoa_don t LEFT JOIN khach_hang k ON k.MAKH=t.MAKH ORDER BY t.NGAYLAP DESC LIMIT 300');
$services=rows('SELECT s.*,d.TENDV,k.HOTENKH FROM sudungdichvu s LEFT JOIN dich_vu d ON d.MADV=s.MADV LEFT JOIN khach_hang k ON k.MAKH=s.MAKH ORDER BY s.THOIGIANSUDUNG DESC LIMIT 300');
page('Đối chiếu dữ liệu phiên bản cũ'); ?><div class="alert">Các bảng cũ được giữ nguyên. Chỉ hiển thị tối đa 300 bản ghi gần nhất ở mỗi bảng. Dịch vụ cũ không có mã đơn và đơn giá lịch sử nên không tự cộng vào đơn mới. Bảng hóa đơn cũ không được cộng vào doanh thu mới để tránh ghi nhận hai lần.</div><div class="panel"><h2>Hóa đơn cũ</h2><table><thead><tr><th>Mã hóa đơn</th><th>Khách hàng</th><th>Ngày lập</th><th>Số tiền đã lưu</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><?=h($i['MAHD'])?></td><td><?=h($i['HOTENKH'])?></td><td><?=h($i['NGAYLAP'])?></td><td><?=money($i['TONGTIEN'])?></td></tr><?php endforeach; ?></tbody></table></div><div class="panel"><h2>Dịch vụ cũ</h2><table><thead><tr><th>Khách hàng</th><th>Dịch vụ</th><th>Thời điểm</th></tr></thead><tbody><?php foreach($services as $s): ?><tr><td><?=h($s['HOTENKH'])?></td><td><?=h($s['TENDV'])?></td><td><?=h($s['THOIGIANSUDUNG'])?></td></tr><?php endforeach; ?></tbody></table></div><?php endpage(); ?>
